contract RicketCoinPreSale is RicketCoinCash {
    uint256 public preSaleEndTime;
    uint256 public preSaleTokensSold;
    uint256 public preSaleMaxTokens;
    uint256 public preSaleMaxAmount;
    uint256 public preSaleMinAmount;
    mapping (address => bool) public preSaleParticipants;
    event PreSaleTokensSold(address indexed _buyer, uint256 _amount);
    function RicketCoinPreSale(uint256 initialSupply, uint256 _sellPrice, uint256 _buyPrice, uint256 _preSaleMaxTokens, uint256 _preSaleMaxAmount, uint256 _preSaleMinAmount) public RocketCoin(initialSupply, _sellPrice, _buyPrice) {}
    function setPreSaleEndTime(uint256 _preSaleEndTime) onlyOwner public {
        preSaleEndTime = _preSaleEndTime;
    }
    function setPreSaleMaxTokens(uint256 _preSaleMaxTokens) onlyOwner public {
        preSaleMaxTokens = _preSaleMaxTokens;
    }
    function setPreSaleMaxAmount(uint256 _preSaleMaxAmount) onlyOwner public {
        preSaleMaxAmount = _preSaleMaxAmount;
    }
    function setPreSaleMinAmount(uint256 _preSaleMinAmount) onlyOwner public {
        preSaleMinAmount = _preSaleMinAmount;
    }
    function preSale(uint256 _amount) payable public {
        require(preSaleEndTime > now);
        require(_amount > 0);
        require(_amount <= preSaleMaxAmount);
        require(_amount >= preSaleMinAmount);
        require(!preSaleParticipants[msg.sender]);
        balances[msg.sender] += _amount;
        preSaleTokensSold += _amount;
        Transfer(this, msg.sender, _amount);
        preSaleParticipants[msg.sender] = true;
        if (preSaleTokensSold >= preSaleMaxTokens) {
            preSaleEndTime = 0;
        }
    }
}

